async ({ delivery: { validate }, shell: { execFile } }) => {
  const v = await validate({ coverage: true, packageCheck: true });
  const [q, pack, diff] = await Promise.all([
    execFile("npm", ["run", "quality:audit"], { maxLines: 20, truncate: "tail" }),
    execFile("npm", ["pack", "--dry-run"]),
    execFile("git", ["diff", "--stat"]),
  ]);
  const p = pack.stderr.split("\n").filter((l) => /size|total files|filename|version/.test(l));
  return { v, q: { code: q.code, out: q.stdout.slice(-500) }, pack: p, diff: diff.stdout };
}
